#!/usr/bin/env python3
"""Compact native typography controls for structured Design text nodes."""

def install(html):
    css=r'''<style id="d2-type-css">#d2-type{margin-top:12px}.d2-type-row{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:5px}.d2-type-row input,.d2-type-row select{width:100%;box-sizing:border-box;border:1px solid #d9d3c7;background:#fbfaf6;padding:6px;font:9px ui-monospace,monospace}.d2-type-align{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;margin-top:5px}.d2-type-align button,#d2-type-apply{margin:0!important;padding:6px 4px!important;font:9px Inter,sans-serif!important}.d2-type-note{margin-top:5px;color:#8b8579;font:9px/1.4 Inter,sans-serif}</style>'''
    panel=r'''<div id="d2-type"><div class="d2-section-title">TYPE</div><div class="d2-type-row"><select id="d2-font"><option value="serif">Editorial Serif</option><option value="sans">Clean Sans</option><option value="mono">Mono</option></select><input id="d2-size" type="number" min="8" max="240" step="1" value="32" title="Font size"></div><div class="d2-type-row"><select id="d2-weight"><option value="400">Regular</option><option value="500">Medium</option><option value="600">Semibold</option><option value="700">Bold</option></select><input id="d2-color" type="color" value="#252525" title="Text color"></div><div class="d2-type-row"><input id="d2-leading" type="number" min="0.7" max="3" step="0.05" value="1.25" title="Line height"><input id="d2-tracking" type="number" min="-10" max="40" step="0.1" value="0" title="Letter spacing px"></div><div class="d2-type-align"><button data-type-align="left">Left</button><button data-type-align="center">Center</button><button data-type-align="right">Right</button></div><button id="d2-type-apply">Apply type</button><div id="d2-type-note" class="d2-type-note">Select a text layer.</div></div>'''
    js=r'''<script id="d2-type-js">(()=>{const g=id=>document.getElementById(id);let align='center';function page(){return ws?.pages?.find(x=>x.id===active)}function node(){return page()?.nodes?.find(n=>n.id===selected?.id)}function sync(){const n=node(),ok=n?.type==='text';['d2-font','d2-size','d2-weight','d2-color','d2-leading','d2-tracking','d2-type-apply'].forEach(id=>g(id).disabled=!ok);document.querySelectorAll('[data-type-align]').forEach(b=>b.disabled=!ok);if(!ok){g('d2-type-note').textContent='Select a text layer.';return}g('d2-font').value=n.font_family||'serif';g('d2-size').value=n.size||18;g('d2-weight').value=String(n.weight||400);g('d2-color').value=n.color||'#252525';g('d2-leading').value=n.line_height||1.25;g('d2-tracking').value=n.letter_spacing||0;align=n.text_align||'center';g('d2-type-note').textContent='Text · '+n.id}document.querySelectorAll('[data-type-align]').forEach(b=>b.onclick=()=>{align=b.dataset.typeAlign});g('d2-type-apply').onclick=async()=>{const n=node();if(!n||n.type!=='text')return;const patch={font_family:g('d2-font').value,size:Math.max(8,Math.min(240,+g('d2-size').value||18)),weight:+g('d2-weight').value||400,color:g('d2-color').value,line_height:Math.max(.7,Math.min(3,+g('d2-leading').value||1.25)),letter_spacing:Math.max(-10,Math.min(40,+g('d2-tracking').value||0)),text_align:align};const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'set_node',page_id:active,id:n.id,patch})});if(r.ok){ws=await r.json();g('status').textContent='saved · r'+ws.revision+' · '+active;g('canvas').src=canvasUrl()}};window.addEventListener('message',e=>{const m=e.data||{};if(m.type==='dore-selection-set'&&m.page_id===active)setTimeout(sync,0)});const timer=setInterval(()=>{if(typeof selected!=='undefined'){clearInterval(timer);setTimeout(sync,50)}},60)})()</script>'''
    return html.replace('</head>',css+'</head>',1).replace('<div id="d2-assets">',panel+'<div id="d2-assets">',1).replace('</body>',js+'</body>',1)
